//! Representation of a Dust function.
//!
//! Prototypes are generated by the compiler (specifically, the emitter) and are used by the virtual
//! machine to execute Dust functions within a program. Dust's prototypes are not self-contained,
//! instructions refer directly to the program's global constant pool and prototype list. This is a
//! key diversion from Lua's design (which is a major influence for Dust), in which each prototype
//! contains its own lists of constants and nested prototypes.
use std::fmt::Debug;

use crate::{
    compiler::Symbol,
    instruction::{Address, Instruction, OperandType},
    r#type::FunctionType,
};

/// Compiled representation of a Dust function.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Prototype {
    pub(crate) symbol: Symbol,
    pub(crate) index: u16,
    pub(crate) function_type: FunctionType,

    pub(crate) instructions: Vec<Instruction>,
    pub(crate) call_arguments: Vec<(Address, OperandType)>,
    pub(crate) drops: Vec<u16>,

    pub(crate) register_count: u16,
}

impl Prototype {
    pub fn dummy() -> Self {
        Self {
            symbol: Symbol::NO_OP,
            index: 0,
            function_type: FunctionType::default(),
            instructions: vec![],
            call_arguments: vec![],
            drops: vec![],
            register_count: 0,
        }
    }
}

impl Default for Prototype {
    fn default() -> Self {
        Self::dummy()
    }
}
